// Differential checks of ArrayFSet-pbo.js against Lean, generated by leanscript --check
import * as M from "./ArrayFSet-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1(0)", () => M.test1(0), "#[7, 2, 1, 3]", false);
check("test1(1)", () => M.test1(1), "#[7, 2, 1, 3]", false);
check("test1(2)", () => M.test1(2), "#[7, 2, 1, 3]", false);
check("test1(5)", () => M.test1(5), "#[7, 2, 1, 3]", false);
check("test1(13)", () => M.test1(13), "#[7, 2, 1, 3]", false);
check("test4([])", () => M.test4([]), "#[]", false);
check("test4([0])", () => M.test4([0]), "#[5]", false);
check("test4([0, 1, 2])", () => M.test4([0, 1, 2]), "#[5, 1, 2]", false);
check("test4([13, 5, 2, 1])", () => M.test4([13, 5, 2, 1]), "#[5, 5, 2, 1]", false);

console.log(`ArrayFSet-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
